#!/usr/bin/env python3
"""Deterministic generator of valid Lammergeier programs of a given size,
for compiler benchmarks. Each "unit" adds a class with fields and methods,
free functions with loops, f-strings, lists, dicts, comprehensions,
``Result``/``?`` propagation and a ``match``-free branchy body, so the
parser, semantic checker and transpiler all see realistic code.

    python3 benchmarks/compiler/gen_program.py --units 50 > /tmp/p.lam
"""
from __future__ import annotations

import argparse

HEADER = """from lamerrors import Result, Error

# Generated by benchmarks/compiler/gen_program.py -- do not edit.
"""

UNIT = """
class Account{i} {{
    func init(self, owner: str, balance: int) {{
        self.owner: str = owner
        self.balance: int = balance
        self.history: list[int] = []
    }}

    func deposit(self, amount: int) -> Result[int] {{
        if amount <= 0 {{
            return Result.Err(Error("ValueError", f"bad amount {{amount}} for {{self.owner}}"))
        }}
        self.balance += amount
        self.history.append(amount)
        return Result.Ok(self.balance)
    }}

    func summary(self) -> str {{
        total: int = 0
        for h in self.history {{
            total += h
        }}
        return f"{{self.owner}}: {{self.balance}} ({{len(self.history)}} ops, {{total}} in)"
    }}
}}

func process{i}(names: list[str], amounts: list[int]) -> Result[dict[str, int]] {{
    out: dict[str, int] = {{}}
    for idx in range(len(names)) {{
        acct: Account{i} = Account{i}(names[idx], idx * {i})
        balance: int = acct.deposit(amounts[idx % len(amounts)])?
        if balance > 1000 and (idx % 2 == 0 or names[idx].startsWith("a")) {{
            out[names[idx]] = balance
        }} elif balance > 10 {{
            out[names[idx] + "_small"] = balance // 2
        }} else {{
            out["other"] = balance
        }}
    }}
    return Result.Ok(out)
}}

func stats{i}(values: list[int]) -> str {{
    squares: list[int] = [v * v for v in values if v % 3 != 0]
    biggest: int = 0
    for s in squares {{
        biggest = max(biggest, s)
    }}
    label: str = "big" if biggest > 100 else "small"
    return f"unit {i}: {{len(squares)}} squares, max {{biggest}} ({{label}})"
}}
"""

MAIN_HEAD = """
func main() {{
    names: list[str] = ["alice", "bob", "carol", "dave", "erin"]
    amounts: list[int] = [5, 50, 500, 5000]
    count: int = 0
"""

MAIN_UNIT = """    r{i}: Result[dict[str, int]] = process{i}(names, amounts)
    if r{i}.ok() {{
        count += len(r{i}.unwrap())
    }}
    _ = stats{i}(amounts)
"""

MAIN_TAIL = """    print(f"done {count}")
}
"""


def generate(units: int) -> str:
    parts = [HEADER]
    parts.extend(UNIT.format(i=i) for i in range(units))
    parts.append(MAIN_HEAD.format())
    parts.extend(MAIN_UNIT.format(i=i) for i in range(units))
    parts.append(MAIN_TAIL)
    return "".join(parts)


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--units", type=int, default=10, help="number of generated units (about 70 lines each)")
    args = ap.parse_args()
    print(generate(args.units), end="")


if __name__ == "__main__":
    main()
